draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // owner
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 30);
  ctx.lineTo(W/2 - 70, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 30);
  ctx.lineTo(W/2 - 30, H/2 + 50);
  ctx.stroke();

  // emotional state
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 - 30, 10 + 5 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  // dog
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 20);
  ctx.lineTo(W/2 + 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 30);
  ctx.lineTo(W/2 + 70, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 30);
  ctx.lineTo(W/2 + 30, H/2 + 50);
  ctx.stroke();

  // dog emotional state mirroring owner
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 - 30, 10 + 5 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
